JOIN lab.analytes a ON a.code = v.analyte_code
WHERE NOT EXISTS (
    SELECT 1 FROM lab.analyte_aliases al
    WHERE al.alias_normalised = regexp_replace(lower(v.alias), '[^a-z0-9]+', '', 'g')
      AND al.practice_id IS NULL
);

