JOIN lab.analytes a ON a.code = v.analyte_code
WHERE NOT EXISTS (
    SELECT 1 FROM lab.reference_ranges rr
    WHERE rr.analyte_id = a.id
      AND rr.sex IS NOT DISTINCT FROM v.sex
      AND rr.age_min_years IS NOT DISTINCT FROM v.age_min
      AND rr.age_max_years IS NOT DISTINCT FROM v.age_max
      AND rr.practice_id IS NULL
);

COMMIT;
